-- Ported from workspaces.conf (originally generated by nwg-displays).
-- https://wiki.hypr.land/Configuring/Workspace-Rules/
--
-- Workspaces 1-10 live on the Samsung (was HDMI-A-1), 11-20 on the Acer (was DP-1).
-- Monitors are matched by description, see monitors.lua.

local m = require("monitors")

for i = 1, 10 do
    hl.workspace_rule({ workspace = tostring(i), monitor = m.SAMSUNG, default = (i == 1) or nil })
end

for i = 11, 20 do
    hl.workspace_rule({ workspace = tostring(i), monitor = m.ACER, default = (i == 11) or nil })
end
